const icon=(id,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[id]?`<path d="${paths[id]}"/>`:`<path d="${paths.spark}"/>`}</svg>`;
const portrait=(id,cls='')=>unitPortrait(id,cls,esc);
const packUI={get portrait(){return portrait;},icon,esc,fmt,resourceArt,get button(){return button;},get modalHeader(){return modalHeader;}};
let collectionRarity='all',collectionOwned=false,collectionMode='all',collectionSort='recommended',collectionRole='all';
let harvestView=null,hudView=null,villageView=null,villageSelected=null,wallEditing=false,villageGeneration=0,pendingVillageAction=null;
let state=createState(),storageOK=true,view='city',target=0,auto=false,modalKind=null,selectedHero='lyra',lastFocus=null,audioCtx=null;
try{const saved=readGameSave(localStorage);if(saved)state=restoreState(JSON.parse(saved));}catch{storageOK=false;}
const cloud=createVillageCloud({getState:()=>state,setState:s=>{const changed=JSON.stringify(state.village.structures)!==JSON.stringify(s.village.structures);state=s;resourceRow();villageView?.sync(state);if(changed&&!$('#village-catalog')?.hidden)refreshCatalog();},save:()=>save(),notice:message=>toast(message,'error')});
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));storageOK=true;}catch{storageOK=false;}syncSaveStatus();}
function syncSaveStatus(){for(const el of [$('#save-status'),$('#village-save-state')])if(el)el.textContent=state.cloud?(cloud.status||'Village lié à ONE'):storageOK?'Progression sauvegardée':'Sauvegarde indisponible — exportez votre partie';}
let toastTimer=null;
function toast(text,type='success'){clearTimeout(toastTimer);const host=$('#toasts'),el=document.createElement('div');el.className='toast '+type;el.innerHTML=icon(type==='error'?'help':'check')+`<span>${esc(text)}</span>`;host.replaceChildren(el);toastTimer=setTimeout(()=>el.remove(),type==='error'?3600:1800);}
function sound(kind='tap'){
 if(!state.settings.sound)return;
 try{audioCtx??=new (window.AudioContext||window.webkitAudioContext)();audioCtx.resume();const t=audioCtx.currentTime;const notes=kind==='win'?[392,494,587,784]:kind==='hit'?[160,90]:[440,660];notes.forEach((f,i)=>{const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type=kind==='hit'?'triangle':'sine';o.frequency.value=f;g.gain.setValueAtTime(0,t+i*.075);g.gain.linearRampToValueAtTime(.045,t+i*.075+.01);g.gain.exponentialRampToValueAtTime(.001,t+i*.075+.25);o.connect(g);g.connect(audioCtx.destination);o.start(t+i*.075);o.stop(t+i*.075+.27);});}catch{}
}
function dispatch(action,message,now=Date.now()){
 try{const before=state.battle?.phase;state=act(state,action,now);save();sound(action.type==='combat'?'hit':'tap');if(state.battle?.phase==='won'&&before!=='won'){auto=false;sound('win');}if(state.battle?.phase==='lost')auto=false;render();if(message)toast(message);return true;}catch(e){toast(e.message,'error');return false;}
}
const navItems=[['city','castle','Ma cité'],['heroes','heroes','Collection'],['campaign','map','Campagne'],['quests','scroll','Quêtes']];
function shell(){
 $('#app').innerHTML=`<aside class="sidebar"><a class="brand" href="#city" aria-label="Valdoria, ma cité"><div class="brand-symbol">${icon('spark')}</div><div><strong>VALDORIA</strong><span>UN UNIVERS ONE</span></div></a><div class="one-mark">UN UNIVERS <b>ONE<span>.</span></b></div><p class="nav-caption">VOTRE AVENTURE</p><nav class="main-nav" aria-label="Navigation du jeu">${navItems.map(([id,ic,title])=>`<button data-nav="${id}" aria-label="${title}">${icon(ic)}<span>${title}</span>${id==='quests'?'<i id="quest-count"></i>':''}</button>`).join('')}</nav><div class="sidebar-promo"><span class="small-sun">${icon('sun')}</span><span class="eyebrow">CHAPITRE I</span><h3>L’éveil<br>des royaumes</h3><p>Chaque légende commence<br>par une première pierre.</p><button data-nav="campaign">Écrire la vôtre ${icon('arrow')}</button></div><div class="sidebar-bottom"><button class="subtle" data-action="help">${icon('help')} Guide du royaume</button><button class="subtle" data-action="settings">${icon('settings')} Réglages & sauvegarde</button><button id="back-one" class="subtle" data-action="back-one" hidden>${icon('back')} Retour à ONE</button><div class="player-box">${portrait('lyra','avatar')}<div><b id="player-name"></b><small id="player-level"></small></div><button class="icon-button" data-action="settings" aria-label="Réglages du profil">${icon('settings')}</button></div></div></aside><div class="game-shell"><header class="topbar"><div class="breadcrumb"><span>ONE</span><i>/</i><strong>Valdoria</strong></div><div class="resources" id="resources"></div><button id="sound-button" class="icon-button" data-action="sound" aria-label="Activer le son"></button></header><main id="main" tabindex="-1"></main><footer class="footer"><span><i class="status-dot"></i><span id="save-status"></span></span><span>Les conquêtes de Valdoria · v52.0</span></footer></div><nav class="mobile-nav" aria-label="Navigation mobile">${navItems.map(([id,ic,title])=>`<button data-nav="${id}" aria-label="${title}">${icon(ic)}<span>${title}</span></button>`).join('')}<button data-action="settings">${icon('settings')}<span>Réglages</span></button></nav>`;
 if(new URLSearchParams(location.search).has('from'))$('#back-one').hidden=false;
 render();
}
function resourceRow(){
 $('#resources').innerHTML=[['gold','gold','Or'],['wood','wood','Bois'],['aether','crystal','Éther'],['gems','spark','Gemmes'],['energy','energy','Énergie']].map(([key,ic,name])=>`<div class="resource resource-${key}" title="${name}${key==='energy'?' · +1 toutes les 90 secondes':''}">${icon(ic)}<div><small>${name}</small><b>${compact(state[key])}${key==='energy'?'<em>/40</em>':''}</b></div></div>`).join('');
 $('#sound-button').innerHTML=icon(state.settings.sound?'sound':'mute');$('#sound-button').setAttribute('aria-label',state.settings.sound?'Couper le son':'Activer le son');$('#sound-button').setAttribute('aria-pressed',String(state.settings.sound));
 $('#player-name').textContent=state.name;$('#player-level').textContent=`Seigneur · Niveau ${1+Math.floor(state.xp/200)}`;
 const ready=QUESTS.filter(q=>state.stats[q.id]>=q.goal&&!state.claimed.includes(q.id)).length;$('#quest-count').textContent=ready||'';$('#quest-count').hidden=!ready;
 syncSaveStatus();hudView?.sync(state);
}
function navigate(id){if(state.progressionVersion&&id==='heroes'&&!collectionAccess(state)){toast('Terminez un camp de formation ou le Hall des héros.','error');return;}if(state.progressionVersion&&id==='campaign'&&state.buildings.castle<3){toast('La campagne se débloque à la citadelle 3.','error');return;}if(state.progressionVersion&&id==='quests'&&!state.village.structures.some(p=>p.kind==='tavern'&&!p.pending)){toast('Les quêtes se débloquent avec la Taverne, à la citadelle 3.','error');return;}if(!['city','heroes','campaign','quests','battle'].includes(id))return;view=id;if(id!=='battle')auto=false;history.replaceState(null,'','#'+id);closeModal();render();window.scrollTo({top:0,behavior:'instant'});}
function render(){
 resourceRow();document.querySelectorAll('[data-nav]').forEach(b=>{b.classList.toggle('active',b.dataset.nav===view);if(b.dataset.nav===view)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});
 const main=$('#main'),collectionScroll=$('.collection-scroll')?.scrollTop||0;document.body.classList.toggle('is-village',view==='city');document.body.classList.toggle('is-collection',view==='heroes');if(view!=='city')document.body.classList.remove('village-ready');
 if(view==='city'&&$('#village-view')){villageView?.sync(state);if(villageSelected&&!villageView?.getPlacement())showPlot(villageSelected);updateVillageStatus();refreshCatalog();if(modalKind==='building')updateBuildingModal();return;}
 if(villageView){villageView.dispose();villageView=null;}hudView?.dispose();hudView=null;harvestView?.dispose();harvestView=null;villageSelected=null;wallEditing=false;villageGeneration++;
 main.innerHTML=view==='heroes'?heroesPage():view==='campaign'?campaignPage():view==='quests'?questsPage():view==='battle'?battlePage():cityPage();
 if(view==='heroes'){const scroller=$('.collection-scroll');if(scroller)scroller.scrollTop=collectionScroll;}
 if(modalKind==='building')updateBuildingModal();
 if(view==='city')mountVillage();
}
function heading(kicker,title,subtitle,right=''){return `<div class="page-heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${subtitle}</p></div>${right}</div>`;}
function button(label,action,cls='button',extra=''){return `<button class="${cls}" data-action="${action}" ${extra}>${label}</button>`;}
function questMini(q){const done=state.claimed.includes(q.id),ready=state.stats[q.id]>=q.goal;return `<button class="quest-mini ${done?'done':''}" data-action="${ready&&!done?'claim':'show-quests'}" data-id="${q.id}"><span class="quest-icon">${icon(done?'check':q.icon)}</span><span><b>${q.title}</b><small>${done?'Récompense récupérée':ready?'Récompense disponible':q.desc}</small></span>${icon(ready&&!done?'gift':'chevron')}</button>`;}
function constructionText(id=buildingId){const q=jobFor(state,id);return q?(q.mode==='construction'?'Construction':'Amélioration')+' · '+formatDuration((q.ends-Date.now())/1000)+' restantes':'';}
function regionCard(r,small=false){
 const unlocked=r.id===0||state.cleared.includes(r.id-1),cleared=state.cleared.includes(r.id);
 return `<button class="region-card region-${r.id} ${unlocked?'':'region-locked'} ${small?'small-region':''}" data-action="region" data-id="${r.id}"><span class="region-art" aria-hidden="true"></span><span class="region-shade"></span><span class="region-top"><span class="region-tag">${cleared?icon('check')+' LIBÉRÉ':unlocked?'CHAPITRE 0'+(r.id+1):icon('lock')+' À DÉCOUVRIR'}</span><span>${icon('energy')} ${r.energy}</span></span><span class="region-copy"><small>${r.zone}</small><strong>${r.short}</strong><span>${unlocked?icon('swords')+' Puissance conseillée '+r.power:'Terminez le chapitre précédent'}<i>${icon(unlocked?'arrow':'lock')}</i></span></span></button>`;
}
function heroWallet(){return `<div class="hero-wallet" aria-label="Vos soldes"><span><i class="one-token" aria-hidden="true">ONE</i><b>${fmt(state.onePoints||0)}</b><small>points ONE</small></span><span>${resourceArt('gems')}<b>${fmt(state.gems)}</b><small>gemmes</small></span></div>`;}
function heroesPage(){return collectionPage(state,collectionRarity,collectionOwned,packUI,{mode:collectionMode,sort:collectionSort,role:collectionRole});}
function campaignPage(){return heading('L’HORIZON VOUS APPARTIENT','Les terres de Valdoria','Quatre territoires. Une menace ancienne. Votre histoire.',`<span class="chapter-complete">${icon('flag')} ${state.cleared.length} / 4 libérés</span>`)+
 `<div class="campaign-banner"><div><span class="eyebrow">CHAPITRE I · L’ÉVEIL DES ROYAUMES</span><h2>La lumière ne<br>se défend pas seule.</h2><p>Des ombres s’éveillent aux frontières.<br>Rassemblez vos héros et répondez à l’appel.</p></div><div class="campaign-badge">${icon('swords')}<b>${fmt(power(state))}</b><span>VOTRE PUISSANCE</span></div></div>${state.battle?.phase==='active'?`<div class="panel resume-panel"><span>${icon('swords')} Un raid vous attend : ${REGIONS[state.battle.region].short}</span>${button('Reprendre le combat '+icon('arrow'),'resume','button gold-button')}</div>`:''}<div class="campaign-grid">${REGIONS.map(r=>regionCard(r)).join('')}</div><div class="campaign-note">${icon('energy')} L’énergie se régénère naturellement : 1 point toutes les 90 secondes. Vos héros retrouvent leur santé entre les raids.</div>`;}
function questsPage(){const count=state.claimed.length;return heading('CHAQUE PAS COMPTE','Le chemin des légendes','Accomplissez vos objectifs et faites grandir votre royaume.',`<span class="chapter-complete">${icon('trophy')} ${count} / ${QUESTS.length} accomplis</span>`)+
 `<div class="quest-page-grid"><section class="quest-list">${QUESTS.map((q,i)=>{const done=state.claimed.includes(q.id),ready=state.stats[q.id]>=q.goal;return `<article class="quest-full ${done?'completed':''}"><div class="quest-full-icon">${icon(done?'check':q.icon)}</div><div class="quest-full-copy"><span class="eyebrow">ÉTAPE 0${i+1}</span><h3>${q.title}</h3><p>${q.desc}</p><div class="quest-progress"><div class="progress-track"><i style="width:${Math.min(100,state.stats[q.id]/q.goal*100)}%"></i></div><span>${Math.min(q.goal,state.stats[q.id])}/${q.goal}</span></div></div><div class="quest-reward"><span>${icon('gold')} ${q.gold} ${icon('spark')} ${q.gems}</span>${button(done?icon('check')+' Récupérée':ready?'Récupérer':'En cours','claim',`button ${ready&&!done?'gold-button':'soft-button'}`,`data-id="${q.id}" ${!ready||done?'disabled':''}`)}</div></article>`;}).join('')}</section><aside class="panel chronicle"><span class="eyebrow">LES MÉMOIRES DU ROYAUME</span><h2>Votre chronique</h2><div>${state.journal.slice(0,9).map(j=>`<article><span class="chronicle-dot"></span><small>${new Date(j.time).toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'})}</small><p>${esc(j.text)}</p></article>`).join('')}</div></aside></div>`;}
function battlePage(){
 const b=state.battle;if(!b)return `<section class="empty-state">${icon('swords')}<h1>L’aventure vous attend</h1><p>Choisissez un territoire et rassemblez vos héros.</p><button class="button gold-button" data-nav="campaign">Explorer les terres</button></section>`;
 if(b.phase!=='active')return resultPage(b);
 const region=REGIONS[b.region],current=b.team[b.actor];if(!b.enemies[target]||b.enemies[target].hp<=0)target=b.enemies.findIndex(e=>e.hp>0);
 return `<div class="battle-heading"><button class="text-button" data-action="leave-battle">${icon('back')} Battre en retraite</button><span>${region.name}</span><span class="turn-badge">TOUR ${b.round}</span></div><section class="battle-arena arena-${b.region}"><div class="arena-background"></div><div class="battle-message"><span class="eyebrow">${region.zone}</span><h2>${auto?'Votre armée combat':current.name+', à vous de jouer.'}</h2><p>${auto?'Touchez une action pour reprendre la main.':'Touchez un adversaire, puis Attaque ou une compétence.'}</p></div><div class="enemy-line">${b.enemies.map((e,i)=>`<button class="fighter enemy ${i===target?'targeted':''} ${e.hp<=0?'fallen':''}" data-action="target" data-id="${i}" ${e.hp<=0?'disabled':''} aria-pressed="${i===target}" aria-label="Cibler ${esc(e.name)}, ${e.hp} points de vie"><div class="enemy-art enemy-art-${i}">${portrait(['berserker','lame-ombre','sorciere-braises'][i])}<span class="enemy-level">${i===2?'BOSS':'NIV. '+(b.region+1)}</span>${e.hp<=0?`<span class="defeated-label">VAINCU</span>`:''}</div><div class="fighter-info"><b>${esc(e.name)}</b><div class="health-bar enemy-health"><i style="width:${e.hp/e.maxHp*100}%"></i></div><small>${e.hp} / ${e.maxHp} PV</small></div>${i===target?'<span class="target-label">CIBLE</span>':''}</button>`).join('')}</div><div class="battle-divider"><span></span>${icon('swords')}<span></span></div><div class="team-line">${b.team.map((h,i)=>`<div class="fighter ally ${i===b.actor?'acting':''} ${h.hp<=0?'fallen':''}"><div class="ally-art">${portrait(h.id)}<span class="ally-label">${i===b.actor?'À VOUS':h.hp<=0?'À TERRE':b.acted.includes(h.id)?'A AGI':'PRÊT'}</span>${h.shield?`<span class="shield-badge">${icon('shield')}</span>`:''}</div><div class="fighter-info"><b>${h.name}</b><div class="health-bar"><i style="width:${h.hp/h.maxHp*100}%"></i></div><small>${h.hp} / ${h.maxHp} PV</small></div></div>`).join('')}</div></section><section class="battle-controls"><div class="current-hero">${portrait(current.id,'avatar')}<span><b>${current.name}</b><small>${current.role}</small></span></div><div class="combat-buttons">${button(icon('swords')+'<span>Attaque<small>Frappe précise</small></span>','combat','button combat-action gold-button','data-move="attack"')}${button(icon('spark')+`<span>${current.skill}<small>${current.cooldown?'Disponible dans '+current.cooldown+' tour(s)':'Compétence spéciale'}</small></span>`,'combat','button combat-action skill-button',`data-move="skill" ${current.cooldown?'disabled':''}`)}${button(icon('shield')+'<span>Garde<small>Protège et soigne</small></span>','combat','button combat-action','data-move="guard"')}${button(icon('potion')+`<span>Potion<small>${state.potions} disponible${state.potions>1?'s':''}</small></span>`,'combat','button combat-action',`data-move="heal" ${!state.potions?'disabled':''}`)}</div><button class="auto-button ${auto?'enabled':''}" data-action="auto" aria-pressed="${auto}">AUTO<span>${auto?'ON':'OFF'}</span></button><button class="auto-button speed-button" data-action="battle-speed" aria-label="Vitesse du combat automatique">VITESSE<span>×${state.settings.combatSpeed||1}</span></button></section><details class="combat-log"><summary>Journal de combat ${icon('scroll')}</summary><div>${b.log.slice(-5).reverse().map(l=>`<p>${esc(l)}</p>`).join('')}</div></details>`;
}
function resultPage(b){const won=b.phase==='won',r=REGIONS[b.region];return `<section class="result-screen ${won?'victory':'defeat'}"><div class="result-backdrop"></div><div class="result-content"><div class="result-medal">${icon(won?'trophy':'shield')}</div><span class="eyebrow">${won?'UNE NOUVELLE PAGE DE VOTRE LÉGENDE':'CHAQUE RETOUR EST UN NOUVEAU DÉPART'}</span><h1>${won?'Victoire !':b.phase==='retreated'?'Retraite tactique':'Le royaume vous attend'}</h1><p>${won?'La lumière revient sur '+r.name.toLowerCase()+'.':'Vos héros ont regagné la cité. Améliorez votre escouade et revenez plus forts.'}</p>${won?`<div class="victory-stars">✦ ✦ ✦</div><div class="rewards-grid">${Object.entries(b.reward||{}).filter(([k,v])=>v>0).map(([key,value])=>`<div>${icon(key==='xp'?'shield':key==='aether'?'crystal':key==='gems'?'spark':key)}<strong>+${fmt(value)}</strong><span>${{gold:'Or',wood:'Bois',aether:'Éther',xp:'Expérience',gems:'Cristaux'}[key]}</span></div>`).join('')}</div><small class="reward-saved">${icon('check')} Récompenses ajoutées à votre royaume</small>`:''}<div class="result-actions">${button('Retour à la cité','end-battle','button soft-button','data-to="city"')}${button(won?'Poursuivre l’aventure '+icon('arrow'):'Renforcer mes héros '+icon('arrow'),'end-battle','button gold-button',`data-to="${won?'campaign':'heroes'}"`)}</div></div></section>`;}
function openModal(kind,html){modalKind=kind;$('#modal').classList.toggle('upgrade-modal',['building','wall-upgrade'].includes(kind));$('#modal').classList.toggle('army-modal',['army','packs','workers','region'].includes(kind));$('#modal').classList.toggle('hero-packs-modal',false);$('#modal').classList.toggle('management-modal',['building','workers'].includes(kind));$('#modal').classList.toggle('royal-modal',['royal-pack','royal-review','royal-reveal','unit-detail','hero-team'].includes(kind));$('#modal').classList.toggle('royal-reveal-modal',kind==='royal-reveal');if(!$('#modal').open)lastFocus=document.activeElement;$('#modal').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();$('#modal').querySelector('button,input')?.focus({preventScroll:true});}
function clearFinishedSiege(){if(modalKind==='siege-result'&&state.siege?.phase!=='active'){state.siege=null;save();villageView?.sync(state);hudView?.sync(state);}}
function closeModal(){clearFinishedSiege();if($('#modal').open)$('#modal').close();modalKind=null;if(lastFocus?.isConnected)lastFocus.focus({preventScroll:true});else if(view==='heroes'&&unitById(selectedHero))document.querySelector(`[data-action=hero-detail][data-id="${selectedHero}"]`)?.focus({preventScroll:true});}
function modalHeader(kicker,title){return `<button class="modal-close icon-button" data-action="close" aria-label="Fermer">${icon('close')}</button><span class="eyebrow">${kicker}</span><h2 id="modal-title">${title}</h2>`;}
let buildingId='castle',wallUpgradeQuote=null,buildingModalStamp='';
function buildingStamp(id){const p=state.village.structures.find(p=>p.id===id),q=jobFor(state,id);return p?[p.level,q?.starts,!!queuedWallFor(state,id),freeWorkers(state),upgradeError(state,p),state.gold,state.wood,upgradeFunds(state,p.essential&&BUILDINGS[id]?buildingCost(state,id):{gold:Math.round(PLOTS[p.kind].gold*p.level*.8),wood:Math.round(PLOTS[p.kind].wood*p.level*.8)}).collectable].join(':'):'';}
function showBuilding(id){const p=state.village.structures.find(p=>p.id===id);if(!p)return;if(p.kind==='builderhut'){showWorkers();return;}buildingId=id;buildingModalStamp=buildingStamp(id);openModal('building',buildingModal(id));fillThumbnails();}
function managementHeader(kicker,title){return `<header class="management-header"><div><span>${kicker}</span><h2 id="modal-title">${title}</h2></div><button class="management-close" data-action="close" aria-label="Fermer">${icon('close')}</button></header>`;}
function prerequisiteAction(r){const plot=state.village.structures.filter(p=>p.kind===r.kind).sort((a,b)=>b.level-a.level)[0];return {label:plot?jobFor(state,plot.id)?'Voir le chantier':'Améliorer':'Construire',kind:r.kind,name:PLOTS[r.kind].name};}
function buildingModal(id){
 const p=state.village.structures.find(p=>p.id===id);if(!p)return '';
 const core=p.essential&&BUILDINGS[id],lvl=core?state.buildings[id]:p.level,kind=p.kind,cost=core?buildingCost(state,id):{gold:Math.round(PLOTS[kind].gold*lvl*.8),wood:Math.round(PLOTS[kind].wood*lvl*.8),seconds:upgradeSeconds(kind,lvl+1)},busy=jobFor(state,id),queued=queuedWallFor(state,id),max=lvl>=MAX_BUILDING_LEVEL,locked=upgradeError(state,p),requirements=kind==='castle'&&state.progressionVersion&&lvl<MAX_BUILDING_LEVEL?citadelRequirements(state):[];
 const missing=requirements.filter(r=>!r.met),ready=requirements.length-missing.length,funds=upgradeFunds(state,cost),collect=!funds.affordable&&funds.collectable;
 const status=max?'Niveau maximum':busy?'Chantier en cours':queued?'Chantier programmé':'Niveau '+lvl+' → '+(lvl+1);
 const preparation=!busy&&!queued&&!max&&requirements.length?`<section class="preparation-card ${missing.length?'':'complete'}"><div class="preparation-title"><b>${missing.length?'Avant d’améliorer':'Tout est prêt'}</b><span>${ready} / ${requirements.length}</span></div>${missing.length?`<p>${missing.length} bâtiment${missing.length>1?'s':''} à préparer</p><div class="preparation-list">${missing.map(r=>{const a=prerequisiteAction(r);return `<button data-action="prepare-building" data-id="${r.kind}" aria-label="${a.label} : ${r.label}"><span data-thumbnail="${r.kind}" data-level="${r.level}"></span><span><b>${r.label}</b><small>${a.label}</small></span>${icon('chevron')}</button>`;}).join('')}</div>`:''}${ready?`<details class="preparation-done"><summary>${icon('check')} ${ready} prérequis rempli${ready>1?'s':''} ${icon('chevron')}</summary><ul>${requirements.filter(r=>r.met).map(r=>'<li>'+icon('check')+r.label+'</li>').join('')}</ul></details>`:''}</section>`:'';
 let notice='',action='';
 if(busy){notice='Le chantier continue même quand vous quittez le jeu.';action=button('Voir les ouvriers','builder-status','button soft-button')+button(icon('spark')+'<span data-speedup-label>Terminer · '+speedupCost(busy)+' gemmes</span>','speedup','button gold-button',`data-id="${id}"`);}
 else if(queued){notice='Un ouvrier commencera dès qu’il sera libre.';action=button('Voir la file des ouvriers','builder-status','button gold-button full-width');}
 else if(max){notice='Ce bâtiment a atteint le niveau 13.';action=button('Retour au village','close','button soft-button full-width');}
 else if(!freeWorkers(state)){notice='Tous les ouvriers sont au travail.';action=button('Voir les ouvriers','builder-status','button gold-button full-width');}
 else if(missing.length){const first=prerequisiteAction(missing[0]);notice='Prochaine étape · '+missing[0].label;action=button(icon('anvil')+first.label+' : '+first.name,'prepare-building','button gold-button full-width',`data-id="${first.kind}"`);}
 else if(locked&&kind!=='castle'&&lvl>=state.buildings.castle&&state.progressionVersion){notice='Citadelle niveau '+(lvl+1)+' requis.';action=button('Améliorer la citadelle','guide-building','button gold-button full-width','data-id="castle"');}
 else{notice=locked||(!funds.affordable?(collect?'Votre production sera récoltée pour payer l’amélioration.':'Il manque '+[['gold','or'],['wood','bois']].filter(([k])=>funds.missing[k]>0).map(([k,label])=>fmt(funds.missing[k])+' '+label).join(' et ')+'.'):'Les ressources sont dépensées uniquement en confirmant.');action=button(icon(collect?'leaf':'anvil')+'<span>'+(collect?'Récolter et améliorer':funds.collectable?'Améliorer au niveau '+(lvl+1):'Ressources insuffisantes')+'</span>','confirm-building-upgrade','button upgrade-confirm',`data-id="${id}" data-level="${lvl}" data-collect="${collect}" ${locked||!funds.collectable?'disabled':''}`);}
 const progress=busy?`<section class="construction-box"><div class="construction-heading"><span class="worker-portrait worker-portrait-${busy.worker||0}" aria-hidden="true"></span><div><b>Ouvrier au travail</b><small>${WORKER_NAMES[busy.worker||0]} s’occupe de ce bâtiment.</small><strong data-countdown>${constructionText(id)}</strong></div></div><div class="progress-track"><i data-construction-progress style="width:${Math.max(0,Math.min(100,100*(Date.now()-busy.starts)/(busy.ends-busy.starts)))}%"></i></div></section>`:queued?'<p class="management-message">'+icon('clock')+' Amélioration dans la file d’attente.</p>':'';
 return `<div class="management-shell">${managementHeader(status,PLOTS[kind].name)}<div class="management-body"><div class="building-overview">${busy?.mode==='construction'?'<div class="building-construction-portrait"><span data-thumbnail="'+kind+'" data-level="'+lvl+'"></span><b>Construction · niveau '+lvl+'</b></div>':upgradePreview(kind,lvl,Math.min(MAX_BUILDING_LEVEL,lvl+1))+upgradeBenefits({...p,level:lvl})}</div>${progress}${preparation}${!busy&&!queued&&!max?`<section class="upgrade-payment"><h3>Coût de l’amélioration</h3>${upgradeCosts(cost,state)}<div class="upgrade-timing"><span>${icon('clock')}<b>${formatDuration(cost.seconds)}</b></span><span>${resourceArt('worker')}<b>1 ouvrier</b></span></div></section>`:''}<div class="management-level-link">${button('Voir les 13 niveaux '+icon('chevron'),'building-levels','text-button',`data-id="${id}"`)}</div></div><footer class="management-footer"><p>${esc(notice)}</p><div class="management-footer-actions">${action}</div></footer></div>`;
}

function refreshBuildingSheet(){
 const host=$('#modal'),body=host.querySelector('.management-body'),scroll=body?.scrollTop||0,details=host.querySelector('.preparation-done')?.open;
 const focused=document.activeElement,action=host.contains?.(focused)?focused.dataset?.action:null,id=focused?.dataset?.id;
 host.innerHTML=buildingModal(buildingId);fillThumbnails();
 const next=host.querySelector('.management-body');if(next)next.scrollTop=scroll;
 const completed=host.querySelector('.preparation-done');if(completed&&details)completed.open=true;
 if(action){const match=[...host.querySelectorAll('[data-action]')].find(el=>el.dataset.action===action&&el.dataset.id===id);match?.focus({preventScroll:true});}
}
function updateBuildingModal(){if(!$('#modal').open||modalKind!=='building')return;const stamp=buildingStamp(buildingId);if(stamp!==buildingModalStamp){buildingModalStamp=stamp;refreshBuildingSheet();}const old=$('#modal').querySelector('[data-countdown]'),busy=jobFor(state,buildingId);if(busy&&old){old.textContent=constructionText(buildingId);const quick=$('[data-speedup-label]');if(quick)quick.textContent='Terminer · '+speedupCost(busy)+' gemmes';const p=$('[data-construction-progress]');if(p)p.style.width=Math.min(100,100*(Date.now()-busy.starts)/(busy.ends-busy.starts))+'%';}else if(old){refreshBuildingSheet();}}
function showWallUpgrade(){
 const ids=villageView?.getWallSelection()||[],plan=wallUpgradePlan(state,ids),eligible=plan.items||[],walls=state.village.structures.filter(p=>eligible.some(q=>q.id===p.id)),minimum=walls.length?Math.min(...walls.map(p=>p.level)):1;
 wallUpgradeQuote={ids:[...ids],signature:plan.signature};
 const levels=new Map();for(const p of walls)levels.set(p.level,(levels.get(p.level)||0)+1);
 const excluded=Object.values(plan.skipped).reduce((n,v)=>n+v,0),next=minimum+1;
 openModal('wall-upgrade',modalHeader('AMÉLIORATION GROUPÉE',`${plan.count||0} rempart${plan.count>1?'s':''} à renforcer`)+`<div class="upgrade-layout"><div class="upgrade-visual">${upgradePreview('wall',minimum)}<div class="upgrade-level-groups">${[...levels].map(([level,count])=>`<span><b>${count}×</b> Niveau ${level} → ${level+1}</span>`).join('')}</div>${upgradeBenefits({kind:'wall',level:minimum})}</div><div class="upgrade-summary">${upgradeCosts(plan,state)}<div class="upgrade-timing"><span>${icon('clock')}<b>${formatDuration(plan.seconds||0)} au total</b></span><span>${resourceArt('worker')}<b>${workerCount(state)} ouvrier${workerCount(state)>1?'s':''}</b></span></div><div class="upgrade-queue-info"><b>${plan.starts||0} maintenant · ${plan.waiting||0} en attente</b><span>+1 niveau par rempart. Les ouvriers enchaînent automatiquement, même pendant votre absence.</span>${excluded?'<small>'+excluded+' rempart(s) exclus : '+(plan.skipped.busy+plan.skipped.queued)+' déjà programmés, '+plan.skipped.maximum+' au maximum, '+plan.skipped.citadel+' limités par la citadelle.</small>':''}</div>${plan.error?'<p class="upgrade-lock">'+icon('lock')+esc(plan.error)+'</p>':''}${button(icon('anvil')+'<span>Améliorer '+(plan.count||0)+' remparts<small>Payer le total et lancer les travaux</small></span>','walls-upgrade-confirm','button upgrade-confirm',plan.error?'disabled':'')}<p class="upgrade-payment-note">Le coût total est payé une seule fois. Les travaux encore en attente peuvent être annulés et remboursés.</p><div class="upgrade-footlinks">${button('Annuler','close','text-button')}</div></div></div>`);fillThumbnails();
}

function showHero(id,options={}){selectedHero=id;if(!unitById(id))return;openModal('unit-detail',unitDetail(state,id,packUI,options));$('#modal').scrollTop=0;}
